/** Set render target frame rate */
export function setTargetFps(module: ProjectMModule, fps: number): void {
    module._set_target_fps(fps);
}

/** Enable adaptive quality governor */
export function setQualityGovernor(module: ProjectMModule, enabled: boolean): void {
    module._set_quality_governor(enabled ? 1 : 0);
}

/** Current quality tier index (0=high, 1=regular, 2=low) */
export function getQualityTier(module: ProjectMModule): number {
    return module._get_quality_tier();
}

/** Current governor internal render-scale factor (1.0/0.75/0.5) */
export function getGovernorRenderScale(module: ProjectMModule): number {
    return module._get_governor_render_scale();
}

/** Current governor blur-level cap (-1 = unlimited, else 0-3) */
export function getGovernorBlurCap(module: ProjectMModule): number {
    return module._get_governor_blur_cap();
}

/** Whether preset shaders are ready */
export function isPresetReady(module: ProjectMModule, minFramesSinceReady: number): number {
    return module._is_preset_ready(minFramesSinceReady);
}

/** Total frames rendered since init */
export function getRenderedFrameCount(module: ProjectMModule): number {
    return module._get_rendered_frame_count();
}

/** Whether last preset switch failed (0/1) */
export function presetSwitchFailed(module: ProjectMModule): number {
    return module._preset_switch_failed();
}

/** Playlists created by init() and not yet destroyed, across all hosts (lifecycle test hook) */
export function livePlaylistCount(module: ProjectMModule): number {
    return module._live_playlist_count();
}

/** Emscripten main-loop timing mode (1 = requestAnimationFrame), -1 before start_render (pacing test hook) */
export function getMainLoopTimingMode(module: ProjectMModule): number {
    return module._get_main_loop_timing_mode();
}

/** Whether OpenMP was compiled in (0/1) */
export function getOmpEnabled(module: ProjectMModule): number {
    return module._get_omp_enabled();
}

/** Configured OpenMP max thread count */
export function getOmpMaxThreads(module: ProjectMModule): number {
    return module._get_omp_max_threads();
}

/** OpenMP threads observed in parallel region */
export function getOmpThreadCountInParallel(module: ProjectMModule): number {
    return module._get_omp_thread_count_in_parallel();
}

/** libomp spin-wait blocktime in ms (0 = sleep immediately, -1 = no libomp) */
export function getOmpBlocktime(module: ProjectMModule): number {
    return module._get_omp_blocktime();
}

/** Begin preset load with optional transpiled GLSL cache key */
export function shaderCacheBeginLoad(module: ProjectMModule, cacheKey: string): void {
    module.ccall('shader_cache_begin_load', null, ['string'], [cacheKey]);
}

/** Inject cached transpiled GLSL (0=warp, 1=composite) */
export function shaderCacheImportGlsl(module: ProjectMModule, shaderType: number, glsl: string): void {
    module.ccall('shader_cache_import_glsl', null, ['number', 'string'], [shaderType, glsl]);
}

/** Clear transpiled GLSL cache key after preset load */
export function shaderCacheEndLoad(module: ProjectMModule): void {
    module._shader_cache_end_load();
}

/** GLSL generator version enum for cache invalidation */
export function getGlslGeneratorVersion(module: ProjectMModule): number {
    return module._get_glsl_generator_version();
}

/** Tear down GL state after WebGL context loss */
export function pmHandleContextLoss(module: ProjectMModule): void {
    module._pm_handle_context_loss();
}

/** Allocate preset-B FBO for transition */
export function dualFboBeginTransition(module: ProjectMModule): boolean {
    return !!module._dual_fbo_begin_transition();
}

/** Finalize dual-FBO transition */
export function dualFboEndTransition(module: ProjectMModule): void {
    module._dual_fbo_end_transition();
}

/** Cancel in-progress dual-FBO transition */
export function dualFboCancelTransition(module: ProjectMModule): void {
    module._dual_fbo_cancel_transition();
}

/** Swap preset A ping-pong buffers */
export function dualFboSwapPresetA(module: ProjectMModule): void {
    module._dual_fbo_swap_preset_a();
}

/** Swap preset B ping-pong buffers */
export function dualFboSwapPresetB(module: ProjectMModule): void {
    module._dual_fbo_swap_preset_b();
}

/** Preset A read FBO handle */
export function dualFboGetAReadFbo(module: ProjectMModule): number {
    return module._dual_fbo_get_a_read_fbo();
}

/** Preset A write FBO handle */
export function dualFboGetAWriteFbo(module: ProjectMModule): number {
    return module._dual_fbo_get_a_write_fbo();
}

/** Preset A read texture handle */
export function dualFboGetAReadTex(module: ProjectMModule): number {
    return module._dual_fbo_get_a_read_tex();
}

/** Preset A write texture handle */
export function dualFboGetAWriteTex(module: ProjectMModule): number {
    return module._dual_fbo_get_a_write_tex();
}

/** Preset B read FBO handle */
export function dualFboGetBReadFbo(module: ProjectMModule): number {
    return module._dual_fbo_get_b_read_fbo();
}

/** Preset B write FBO handle */
export function dualFboGetBWriteFbo(module: ProjectMModule): number {
    return module._dual_fbo_get_b_write_fbo();
}

/** Preset B read texture handle */
export function dualFboGetBReadTex(module: ProjectMModule): number {
    return module._dual_fbo_get_b_read_tex();
}

/** Preset B write texture handle */
export function dualFboGetBWriteTex(module: ProjectMModule): number {
    return module._dual_fbo_get_b_write_tex();
}

/** Whether preset-A FBO is allocated (lazily allocated per transition) */
export function dualFboIsPresetAAllocated(module: ProjectMModule): boolean {
    return !!module._dual_fbo_is_preset_a_allocated();
}

/** Whether preset-B FBO is allocated */
export function dualFboIsPresetBAllocated(module: ProjectMModule): boolean {
    return !!module._dual_fbo_is_preset_b_allocated();
}

/** Idle seconds before the preset-A FBO pair is reclaimed (0=immediate, <0=never) */
export function dualFboSetIdleReleaseSeconds(module: ProjectMModule, seconds: number): void {
    module._dual_fbo_set_idle_release_seconds(seconds);
}

/** Configured preset-A idle release threshold in seconds */
export function dualFboGetIdleReleaseSeconds(module: ProjectMModule): number {
    return module._dual_fbo_get_idle_release_seconds();
}

/** Whether preset-B shaders are ready */
export function dualFboIsPresetBReady(module: ProjectMModule): boolean {
    return !!module._dual_fbo_is_preset_b_ready();
}

/** Dual-FBO format (0=RGBA16F, 1=RGBA32F, 2=RGBA8 — the fboPrecision numbering) */
export function dualFboGetFormat(module: ProjectMModule): number {
    return module._dual_fbo_get_format();
}

/** What this host negotiated with WebGL, packed in an int (0 before init): bit0 has a context, bit1 EXT_color_buffer_float, bit2 EXT_float_blend, bit3 WEBGL_lose_context present, bits 8-9 active dual-FBO format (0=RGBA16F, 1=RGBA32F, 2=RGBA8). Decoded into ProjectMContext.contextSnapshot */
export function getContextSnapshot(module: ProjectMModule): number {
    return module._get_context_snapshot();
}

/** Render preset A into dual FBO */
export function dualFboRenderPresetA(module: ProjectMModule): void {
    module._dual_fbo_render_preset_a();
}

/** Render preset B into dual FBO */
export function dualFboRenderPresetB(module: ProjectMModule): void {
    module._dual_fbo_render_preset_b();
}

/** Start visual preset transition blend */
export function transitionStart(module: ProjectMModule): void {
    module._transition_start();
}

/** Cancel active transition */
export function transitionCancel(module: ProjectMModule): void {
    module._transition_cancel();
}

/** Whether a transition is in progress */
export function transitionIsActive(module: ProjectMModule): boolean {
    return !!module._transition_is_active();
}

/** Current transition blend factor 0..1 */
export function transitionGetBlend(module: ProjectMModule): number {
    return module._transition_get_blend();
}

/** Set transition duration in seconds */
export function transitionSetDuration(module: ProjectMModule, seconds: number): void {
    module._transition_set_duration(seconds);
}

/** Configured transition duration in seconds */
export function transitionGetDuration(module: ProjectMModule): number {
    return module._transition_get_duration();
}

/** Pin libprojectM's RNG to a seed so a preset renders identical pixels run to run */
export function setDeterministicSeed(module: ProjectMModule, enabled: boolean, seed: number): void {
    module._set_deterministic_seed(enabled ? 1 : 0, seed);
}

/** Whether deterministic RNG seeding is active */
export function isDeterministicSeed(module: ProjectMModule): boolean {
    return !!module._is_deterministic_seed();
}

/** Drive the engine from a virtual clock where frame N happens at N/fps (golden-image capture only, never perf runs) */
export function setDeterministicClock(module: ProjectMModule, enabled: boolean, fps: number): void {
    module._set_deterministic_clock(enabled ? 1 : 0, fps);
}

/** Whether the virtual clock is active */
export function isDeterministicClock(module: ProjectMModule): boolean {
    return !!module._is_deterministic_clock();
}

/** The host time base in milliseconds: virtual when the clock is on, real otherwise */
export function deterministicNowMs(module: ProjectMModule): number {
    return module._deterministic_now_ms();
}

/** Frames ticked since the virtual clock was last enabled */
export function deterministicFrameIndex(module: ProjectMModule): number {
    return module._deterministic_frame_index();
}

/** Pause/resume the requestAnimationFrame main loop so a harness can drive render_frame() itself */
export function setRenderLoopPaused(module: ProjectMModule, paused: boolean): void {
    module._set_render_loop_paused(paused ? 1 : 0);
}

/** Tempo in BPM from the rhythm analysis (0 while the tracker is not confident) */
export function getRhythmBpm(module: ProjectMModule): number {
    return module._get_rhythm_bpm();
}

/** Beat phase 0..1, 0 = the (predicted) beat */
export function getRhythmBeatPhase(module: ProjectMModule): number {
    return module._get_rhythm_beat_phase();
}

/** Bar phase 0..1 over four beats, 0 = downbeat */
export function getRhythmBarPhase(module: ProjectMModule): number {
    return module._get_rhythm_bar_phase();
}

/** Tempo tracker confidence 0..1 (1 while a tempo hint is set) */
export function getRhythmConfidence(module: ProjectMModule): number {
    return module._get_rhythm_confidence();
}

/** Beats counted since the engine started */
export function getRhythmBeatIndex(module: ProjectMModule): number {
    return module._get_rhythm_beat_index();
}

/** Section index, incremented on every detected section change */
export function getRhythmSection(module: ProjectMModule): number {
    return module._get_rhythm_section();
}

/** Use a known tempo (MIDI clock, track BPM) instead of estimating it (0 goes back to estimating) */
export function setRhythmHint(module: ProjectMModule, bpm: number): void {
    module._set_rhythm_hint(bpm);
}

/** Switch presets on the timer (0), every N bars (1) or on a detected section change (2), bars 0 = 16 */
export function setPresetSwitchPolicy(module: ProjectMModule, policy: number, bars: number): void {
    module._set_preset_switch_policy(policy, bars);
}

/** Preset switch policy (0 timer, 1 bars, 2 section) */
export function getPresetSwitchPolicy(module: ProjectMModule): number {
    return module._get_preset_switch_policy();
}

/** Crossfade length in beats, resolved against the tempo when each crossfade starts (0 = use seconds) */
export function transitionSetDurationBeats(module: ProjectMModule, beats: number): void {
    module._transition_set_duration_beats(beats);
}

/** Configured crossfade length in beats (0 = seconds) */
export function transitionGetDurationBeats(module: ProjectMModule): number {
    return module._transition_get_duration_beats();
}

/** Make beat-detection hard cuts wait for the next beat */
export function setHardCutOnBeat(module: ProjectMModule, enabled: boolean): void {
    module._set_hard_cut_on_beat(enabled ? 1 : 0);
}

/** Report beats, bars and section changes to globalThis.pmOnRhythmEvent (off by default) */
export function setRhythmEvents(module: ProjectMModule, enabled: boolean): void {
    module._set_rhythm_events(enabled ? 1 : 0);
}

/** Turn the temporal flash limiter on or off (off by default, see docs/FLASH_LIMITER.md) */
export function setFlashLimitEnabled(module: ProjectMModule, enabled: boolean): void {
    module._set_flash_limit_enabled(enabled ? 1 : 0);
}

/** Whether the flash limiter is on */
export function getFlashLimitEnabled(module: ProjectMModule): boolean {
    return !!module._get_flash_limit_enabled();
}

/** Span of mean relative luminance (0.005..1, default 0.06) the presented frames may cover within the limiter's ~1/3 s memory */
export function setFlashLimitThreshold(module: ProjectMModule, threshold: number): void {
    module._set_flash_limit_threshold(threshold);
}

/** The flash limiter's threshold */
export function getFlashLimitThreshold(module: ProjectMModule): number {
    return module._get_flash_limit_threshold();
}

/** Frames the flash limiter blended toward the previous frame since it was enabled (reads back from the GPU: poll a few times a second at most) */
export function getFlashLimitClampedFrames(module: ProjectMModule): number {
    return module._get_flash_limit_clamped_frames();
}

/** emscripten_webgl_commit_frame() calls since the host was created (0 unless the host presents manually) */
export function getCommittedFrameCount(module: ProjectMModule): number {
    return module._get_committed_frame_count();
}

/** Read back the next rendered frame (1 accepted, 0 no context), replacing an unclaimed capture */
export function captureFrameRequest(module: ProjectMModule): number {
    return module._capture_frame_request();
}

/** Capture state: 0 idle, 1 requested, 2 pending (GPU read in flight), 3 ready, 4 failed (never waits) */
export function captureFrameStatus(module: ProjectMModule): number {
    return module._capture_frame_status();
}

/** capture_frame_status(), but wait=true takes a pending capture now, waiting for the GPU if it must */
export function captureFrameResolve(module: ProjectMModule, wait: boolean): number {
    return module._capture_frame_resolve(wait ? 1 : 0);
}

/** Heap address of the ready capture's RGBA8 pixels, top row first (0 unless ready) */
export function captureFrameDataPtr(module: ProjectMModule): number {
    return module._capture_frame_data_ptr();
}

/** Width in pixels of the last capture */
export function captureFrameWidth(module: ProjectMModule): number {
    return module._capture_frame_width();
}

/** Height in pixels of the last capture */
export function captureFrameHeight(module: ProjectMModule): number {
    return module._capture_frame_height();
}

/** get_rendered_frame_count() right after the captured frame */
export function captureFrameIndex(module: ProjectMModule): number {
    return module._capture_frame_index();
}

/** Free the captured pixels */
export function captureFrameRelease(module: ProjectMModule): void {
    module._capture_frame_release();
}

